// Pull the raw JSON array from the HTTP response body
const ids = $input.first().json;

if (!Array.isArray(ids) || ids.length === 0) {
  throw new Error('HN top stories API returned empty or invalid data');
}

// Take only the first 5 IDs to minimise API calls
const top5 = ids.slice(0, 5);

// Emit one item per ID so the next node can parallelise fetches
return top5.map(id => ({ json: { storyId: id } }));

// Aggregate all 5 story items into a single digest object
const items = $input.all();

const stories = items
  .map(i => i.json)
  .filter(s => s && s.type === 'story' && s.title)
  .sort((a, b) => (b.score || 0) - (a.score || 0));

if (stories.length === 0) {
  throw new Error('No valid stories found after enrichment');
}

return [{ json: { stories, fetchedAt: new Date().toISOString() } }];

const { stories, fetchedAt } = $input.first().json;

const lines = stories.map((s, i) => {
  const pts = s.score || 0;
  const comments = s.descendants || 0;
  const url = s.url || `https://news.ycombinator.com/item?id=${s.id}`;
  return `**${i + 1}. ${s.title}**\n> Score: ${pts} pts | Comments: ${comments} | By: ${s.by}\n> <${url}>`;
}).join('\n\n');

const embed = {
  username: 'HN Morning Brief',
  embeds: [{
    title: '🔥 Top HackerNews Stories (Score ≥ 100)',
    description: lines,
    color: 16744272,
    footer: { text: `Fetched at ${fetchedAt}` }
  }]
};

return [{ json: embed }];

const { stories, fetchedAt } = $input.first().json;

const lines = stories.map((s, i) => {
  const pts = s.score || 0;
  const url = s.url || `https://news.ycombinator.com/item?id=${s.id}`;
  return `${i + 1}. **${s.title}** (${pts} pts)\n   <${url}>`;
}).join('\n');

const embed = {
  username: 'HN Morning Brief',
  embeds: [{
    title: '📰 HackerNews Digest – Quiet Day',
    description: lines,
    color: 3447003,
    footer: { text: `Fetched at ${fetchedAt}` }
  }]
};

return [{ json: embed }];

// Collect error information from any failed node
const errItem = $input.first();
const nodeName = errItem.json.nodeName || 'Unknown node';
const errorMsg = errItem.json.message || JSON.stringify(errItem.json);

const payload = {
  username: 'HN Brief – Error Monitor',
  embeds: [{
    title: '⚠️ Workflow Error',
    description: `**Node:** ${nodeName}\n**Error:** ${errorMsg}\n**Time:** ${new Date().toISOString()}`,
    color: 16711680
  }]
};

return [{ json: payload }];
